### Agent as a Service (API)

Wrap your agent in a FastAPI server with streaming support:

```python
from fastapi import FastAPI
from fastapi.responses import StreamingResponse
from pydantic import BaseModel
import asyncio
import json

app = FastAPI(title="Agent API")

# Your pre-built agent
agent = create_react_agent(llm, tools)

class AgentRequest(BaseModel):
    message: str
    thread_id: str = "default"
    stream: bool = False

@app.post("/invoke")
async def invoke_agent(request: AgentRequest):
    """Synchronous agent invocation — returns complete result."""
    result = await agent.ainvoke(
        {"messages": [{"role": "user", "content": request.message}]},
        config={"configurable": {"thread_id": request.thread_id}},
    )
    return {"response": result["messages"][-1].content}

@app.post("/stream")
async def stream_agent(request: AgentRequest):
    """Streaming agent invocation — returns Server-Sent Events."""
    async def event_generator():
        async for event in agent.astream_events(
            {"messages": [
                {"role": "user", "content": request.message}
            ]},
            version="v2",
            config={
                "configurable": {"thread_id": request.thread_id}
            },
        ):
            if event["event"] == "on_chat_model_stream":
                token = event["data"]["chunk"].content
                if token:
                    yield (
                        f"data: {json.dumps({'type': 'token', 'content': token})}\n\n"
                    )
            elif event["event"] == "on_tool_start":
                yield (
                    f"data: {json.dumps({'type': 'tool_start', 'name': event['name']})}\n\n"
                )
            elif event["event"] == "on_tool_end":
                yield (
                    f"data: {json.dumps({'type': 'tool_end', 'name': event['name']})}\n\n"
                )
            elif event["event"] == "on_chain_end":
                yield f"data: {json.dumps({'type': 'done'})}\n\n"

    return StreamingResponse(
        event_generator(), media_type="text/event-stream"
    )

# WebSocket support for bidirectional streaming
from fastapi import WebSocket

@app.websocket("/ws")
async def websocket_agent(websocket: WebSocket):
    await websocket.accept()
    try:
        while True:
            data = await websocket.receive_text()
            request = json.loads(data)
            async for event in agent.astream_events(
                {"messages": [
                    {"role": "user", "content": request["message"]}
                ]},
                version="v2",
            ):
                if event["event"] == "on_chat_model_stream":
                    token = event["data"]["chunk"].content
                    if token:
                        await websocket.send_text(
                            json.dumps({
                                "type": "token",
                                "content": token,
                            })
                        )
    except Exception:
        await websocket.close()
```

Run with: `uvicorn agent_api:app --host 0.0.0.0 --port 8000`

### Async Task Processing with Celery

For long-running agent tasks, use a task queue:

```python
# tasks.py
from celery import Celery
import redis

celery_app = Celery(
    "agent_tasks", broker="redis://localhost:6379/0"
)

# Redis for storing results
result_store = redis.Redis(host="localhost", port=6379, db=1)

@celery_app.task(bind=True, max_retries=3)
def run_agent_task(
    self, task_id: str, message: str, agent_config: dict
):
    """Execute an agent task asynchronously with retries."""
    try:
        result_store.set(f"task:{task_id}:status", "running")

        agent = build_agent(agent_config)
        result = agent.invoke(
            {"messages": [{"role": "user", "content": message}]}
        )

        response = result["messages"][-1].content
        result_store.set(f"task:{task_id}:status", "completed")
        result_store.set(f"task:{task_id}:result", response)
        return {
            "task_id": task_id,
            "status": "completed",
            "result": response,
        }

    except Exception as exc:
        result_store.set(f"task:{task_id}:status", "failed")
        raise self.retry(exc=exc, countdown=60)

# Submit a task
import uuid
task_id = str(uuid.uuid4())
run_agent_task.delay(
    task_id, "Analyze this document", {"model": "gpt-4o"}
)

# Check status later
status = result_store.get(f"task:{task_id}:status")
result = result_store.get(f"task:{task_id}:result")
```

### CI/CD for Agents

Agents are software — they need the same engineering discipline as any production system.

#### Testing Agents in CI

```python
# tests/test_agent.py
import pytest

class TestResearchAgent:
    @pytest.fixture
    def agent(self):
        return ResearchAgent()

    def test_handles_simple_query(self, agent):
        """Agent should return a non-empty response for a simple question."""
        result = agent.run("What is RAG?")
        assert result is not None
        assert len(result) > 50  # Should be substantive

    def test_tool_selection(self, agent):
        """Agent should select the correct tool for a research task."""
        plan = agent.create_plan("Search for recent AI papers")
        assert any(
            step["tool"] == "search" for step in plan
        )

    def test_handles_empty_input_gracefully(self, agent):
        """Agent should not crash on empty or invalid input."""
        result = agent.run("")
        assert result is not None

    @pytest.mark.integration
    def test_end_to_end_research(self, agent):
        """Full pipeline: plan → execute → return result."""
        result = agent.run(
            "Research MCP protocol and summarize findings"
        )
        assert "MCP" in result or "Model Context Protocol" in result
```

#### Prompt Versioning

```python
from dataclasses import dataclass, field
from datetime import datetime
from pathlib import Path
import json
import hashlib

@dataclass
class PromptVersion:
    version: str
    content: str
    created_at: str
    checksum: str
    metadata: dict = field(default_factory=dict)

class PromptRegistry:
    """Version and rollback prompt templates."""

    def __init__(self, storage_path: str = "prompts/"):
        self.path = Path(storage_path)
        self.path.mkdir(exist_ok=True)

    def save(
        self, name: str, content: str, metadata: dict = None
    ) -> str:
        """Save a new version of a prompt."""
        versions = self._list_versions(name)
        version = f"v{len(versions) + 1}"
        checksum = hashlib.sha256(content.encode()).hexdigest()[:12]

        prompt_data = {
            "version": version,
            "content": content,
            "created_at": datetime.now().isoformat(),
            "checksum": checksum,
            "metadata": metadata or {},
        }

        version_file = self.path / f"{name}_{version}.json"
        version_file.write_text(json.dumps(prompt_data, indent=2))

        # Update the 'latest' pointer
        latest = self.path / f"{name}_latest.json"
        latest.write_text(version)

        return version

    def load(self, name: str, version: str = "latest") -> str:
        """Load a specific version (or latest) of a prompt."""
        if version == "latest":
            latest_file = self.path / f"{name}_latest.json"
            version = latest_file.read_text().strip()

        version_file = self.path / f"{name}_{version}.json"
        data = json.loads(version_file.read_text())
        return data["content"]

    def _list_versions(self, name: str) -> list[str]:
        return sorted(
            f.stem.split("_")[-1]
            for f in self.path.glob(f"{name}_v*.json")
        )

# Usage
registry = PromptRegistry()
registry.save(
    "researcher_system",
    "You are a research assistant. Be thorough.",
    {"author": "alice"},
)
registry.save(
    "researcher_system",
    "You are a senior research analyst. Cite sources.",
    {"author": "bob"},
)
print(registry.load("researcher_system"))        # Latest version
print(registry.load("researcher_system", "v1"))   # First version
```

#### A/B Testing Agent Prompts

```python
import random
from collections import defaultdict

class PromptABTest:
    """A/B test different prompt versions and track quality metrics."""

    def __init__(self, prompt_a: str, prompt_b: str):
        self.prompts = {"A": prompt_a, "B": prompt_b}
        self.results = defaultdict(
            lambda: {"responses": [], "scores": []}
        )

    def get_prompt(self) -> tuple[str, str]:
        """Randomly assign a variant (50/50 split)."""
        variant = random.choice(["A", "B"])
        return variant, self.prompts[variant]

    def record_outcome(
        self, variant: str, response: str, score: float
    ):
        """Record the quality score for a given variant."""
        self.results[variant]["responses"].append(response)
        self.results[variant]["scores"].append(score)

    def get_stats(self) -> dict:
        """Compute statistics for each variant."""
        stats = {}
        for variant, data in self.results.items():
            scores = data["scores"]
            if scores:
                stats[variant] = {
                    "n": len(scores),
                    "mean_score": sum(scores) / len(scores),
                    "min": min(scores),
                    "max": max(scores),
                }
        return stats

# Usage
ab_test = PromptABTest(
    prompt_a="Answer concisely in 1-2 sentences.",
    prompt_b="Provide a detailed explanation with examples.",
)

for query in [
    "What is MCP?",
    "Explain RAG.",
    "How do multi-agent systems work?",
]:
    variant, prompt = ab_test.get_prompt()
    response = llm.invoke(
        f"{prompt}\n\nQuestion: {query}"
    ).content
    score = float(input("Rate this response (1-5): "))
    ab_test.record_outcome(variant, response, score)

print(ab_test.get_stats())
# {'A': {'n': 3, 'mean_score': 4.0, ...},
#  'B': {'n': 3, 'mean_score': 3.7, ...}}
```
